def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 1.5:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    slots = max(1, int(supply // WATER_REQ))
    scarcity = len(alive) + 1 - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if scarcity >= 3:
        urgency += 2
    elif scarcity >= 2:
        urgency += 1

    if supply <= 16:
        urgency += 2
    elif supply <= 19:
        urgency += 1

    if desperate_count >= 2:
        urgency += 1

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    if urgency >= 6:
        target = max(DAILY_SALARY * 0.95, min(highest_prev + 2.0, DAILY_SALARY * 1.15))
    elif urgency >= 4:
        target = max(DAILY_SALARY * 0.72, min(avg_prev + 3.0, DAILY_SALARY * 0.98))
    elif urgency >= 2:
        target = max(DAILY_SALARY * 0.48, min(avg_prev * 0.82 + 2.0, DAILY_SALARY * 0.78))
    else:
        target = DAILY_SALARY * 0.32

    if highest_prev > 200:
        target = min(target, DAILY_SALARY * 0.76)
    elif highest_prev > 120 and urgency < 5:
        target = min(target, DAILY_SALARY * 0.68)

    if rich_count == 0 and scarcity <= 1 and urgency <= 2:
        target = min(target, DAILY_SALARY * 0.4)

    remaining_days = max(0, 10 - int(day) + 1)
    reserve_floor = max(0.0, remaining_days * DAILY_SALARY * 0.18)
    spend_cap = budget if urgency >= 5 else max(0.0, budget - reserve_floor)

    if spend_cap <= 0:
        return float(min(budget, DAILY_SALARY * 0.2))

    bid = min(target, spend_cap, budget)
    if hp <= 2 or no_water_days >= 2:
        bid = min(max(bid, DAILY_SALARY * 0.9), budget)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    # Base bid as fraction of salary
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 2:
        bid_frac = 0.95
    else:
        bid_frac = 0.6
    target = min(my_status['budget'], DAILY_SALARY * bid_frac)
    # Check opponents' previous trace (only from yesterday)
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if alive_opponents:
        max_prev_bid = 0
        for opp in alive_opponents:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                max_prev_bid = max(max_prev_bid, prev['bid'])
        # If someone bid very high yesterday, avoid wasteful bidding; else try to beat max
        if max_prev_bid > 0:
            if my_status['hp'] > 3:
                # If healthy, bid just above the second highest? But we don't have second. Use 60% of max? Simpler: bid 0.6 * salary or just above max if affordable
                if max_prev_bid < DAILY_SALARY * 0.7:
                    target = min(my_status['budget'], max_prev_bid + 1.0)
                else:
                    target = min(my_status['budget'], DAILY_SALARY * 0.4)
            else:
                # Low HP: bid high
                target = min(my_status['budget'], max(DAILY_SALARY * 0.85, max_prev_bid + 0.5))
    # Ensure target is not above budget
    bid = min(my_status['budget'], target)
    # Ensure positive bid
    return max(0.0, bid)
